#!/usr/bin/env python3
"""Generate the chess FIDE Elo project page and compact data asset."""
from __future__ import annotations
import csv, json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
INPUT = ROOT / "_scripts/data/chess_elo"
ASSET = ROOT / "assets/js/chess-elo-data.js"
PAGE = ROOT / "_pages/chess-elo.html"

files = sorted(INPUT.glob("top100_????-??.csv"))
if not files:
    raise SystemExit(f"No snapshots in {INPUT}")
dates, means, by_name = [], [], {}
for path in files:
    date = path.stem.removeprefix("top100_")
    with path.open(newline="", encoding="utf-8") as f:
        rows = []
        for row in csv.DictReader(f):
            row["rating"], row["rank"] = int(row["rating"]), int(row["rank"])
            row["name"] = {"Kasparov, Gary": "Kasparov, Garry"}.get(row["name"], row["name"])
            rows.append(row)
    rows.sort(key=lambda r: r["rank"])
    dates.append(date)
    means.append(round(sum(r["rating"] for r in rows) / len(rows), 3))
    for row in rows:
        player = by_name.setdefault(row["name"], {"name": row["name"], "fed": row["fed"], "series": []})
        player["series"].append([date, row["rating"], row["rank"]])
ref = means[-1]
for player in by_name.values():
    peak_i = max(range(len(player["series"])), key=lambda i: player["series"][i][1])
    date, rating, rank = player["series"][peak_i]
    player["peak"] = {"date": date, "rating": rating, "rank": rank,
                       "calibrated": round(rating - means[dates.index(date)] + ref, 3)}
players = sorted(by_name.values(), key=lambda p: (-p["peak"]["rating"], p["name"]))
data = {"dates": dates, "means": means, "referenceMean": ref, "players": players,
        "coverage": {"start": dates[0], "end": dates[-1], "lists": len(files),
                     "players": len(players), "source": "Community FIDE-list mirrors",
                     "shortLists": ["2020-04", "2020-05"]}}
ASSET.parent.mkdir(parents=True, exist_ok=True)
ASSET.write_text("window.CHESS_ELO_DATA = " + json.dumps(data, separators=(",", ":"), ensure_ascii=False) + ";\n", encoding="utf-8")

front = """---
layout: single
title: \"Chess FIDE Elo Explorer\"
classes: wide
author_profile: false
permalink: /projects/chess-elo/
---"""
template = r'''<!DOCTYPE html>
<html lang="en" data-theme="light"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Chess FIDE Elo Explorer</title></head><body>
<div id="chess-app">
<style>
#chess-app{--ink:#172033;--muted:#647084;--line:#dce3ec;--soft:#f6f8fb;--blue:#2457d6;--blue-soft:#edf3ff;--gold:#b7791f;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;color:var(--ink);line-height:1.55;max-width:1120px;margin:auto}#chess-app *{box-sizing:border-box}#chess-app h1,#chess-app h2,#chess-app h3{color:var(--ink);letter-spacing:-.025em}#chess-app h1{font-size:clamp(2rem,4vw,3.35rem);line-height:1.05;margin:0 0 .7rem}#chess-app h2{font-size:1.35rem;margin:0}#chess-app h3{font-size:1rem;margin:.2rem 0 .35rem}.eyebrow{color:var(--blue);font-size:.72rem;font-weight:800;letter-spacing:.13em;text-transform:uppercase;margin:0 0 .7rem}.hero{padding:2.2rem 0 1.7rem;max-width:790px}.sub{font-size:1.1rem;color:var(--muted);margin:0;max-width:700px}.warning{display:flex;gap:.8rem;align-items:flex-start;background:#fffaf0;border:1px solid #f1d9a4;border-left:4px solid var(--gold);border-radius:10px;padding:1rem 1.1rem;margin:0 0 1.2rem}.warning strong{color:#6d4b11}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:.8rem;margin:0 0 1.2rem}.kpi,.panel,.method-card{background:#fff;border:1px solid var(--line);border-radius:14px}.kpi{padding:1rem 1.05rem;box-shadow:0 5px 18px rgba(27,45,75,.04)}.k-label{color:var(--muted);font-size:.7rem;font-weight:800;letter-spacing:.09em;text-transform:uppercase}.k-value{font-size:1.55rem;font-weight:750;line-height:1.2;margin-top:.2rem;font-variant-numeric:tabular-nums}.panel{padding:1.25rem;margin:0 0 1.2rem;box-shadow:0 8px 28px rgba(27,45,75,.045)}.panel-head{display:flex;justify-content:space-between;gap:1rem;align-items:flex-start;margin-bottom:.9rem}.panel-head p{margin:.2rem 0 0;color:var(--muted);font-size:.88rem}.controls{display:flex;flex-wrap:wrap;align-items:center;gap:.55rem;padding:.75rem;background:var(--soft);border:1px solid var(--line);border-radius:10px}.controls label{font-size:.82rem;font-weight:700}.controls input{min-width:210px}.controls input,.controls select,.controls button{font:inherit;font-size:.84rem;border:1px solid #cbd5e1;border-radius:7px;background:#fff;padding:.45rem .65rem;color:var(--ink)}.controls input:focus,.controls button:focus,.controls select:focus{outline:3px solid #cfe0ff;outline-offset:1px}.controls button{cursor:pointer;font-weight:700}.controls .mode.active{background:var(--blue);border-color:var(--blue);color:#fff}.chart{height:420px;margin-top:1rem;background:#fbfcfe;border:1px solid var(--line);border-radius:10px;overflow:hidden}.chart svg{width:100%;height:100%}.legend{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:.75rem}.chip{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:99px;overflow:hidden;background:#fff}.chip.off{background:var(--soft)}.chip-toggle,.chip-remove,.sort{cursor:pointer;border:0;background:transparent;color:inherit;font:inherit}.chip-toggle{padding:.34rem .55rem;font-size:.78rem}.chip-toggle[aria-pressed="false"]{color:#9aa5b5;text-decoration:line-through}.chip-remove{padding:.34rem .55rem;border-left:1px solid var(--line);font-size:1rem;line-height:1}.sort{font-weight:800;color:inherit;text-transform:inherit;letter-spacing:inherit;padding:0}.sort:hover{color:var(--blue)}.note,.muted{color:var(--muted);font-size:.84rem}.note{margin:.65rem 0 0}.method-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:.8rem;margin:0 0 1.2rem}.method-card{padding:1rem 1.05rem;background:linear-gradient(145deg,#fff,#f8faff)}.method-card p{color:var(--muted);font-size:.85rem;margin:0}.method-number{display:inline-grid;place-items:center;width:1.55rem;height:1.55rem;border-radius:50%;background:var(--blue-soft);color:var(--blue);font-size:.75rem;font-weight:800;margin-bottom:.45rem}.table-toolbar{display:flex;justify-content:space-between;align-items:center;gap:.8rem;margin:.8rem 0}.table-toolbar input{font:inherit;font-size:.84rem;border:1px solid #cbd5e1;border-radius:7px;padding:.45rem .65rem;min-width:220px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px}.table{width:100%;border-collapse:collapse;font-size:.84rem}.table th,.table td{padding:.62rem .75rem;border-bottom:1px solid #e8edf3;text-align:left;white-space:nowrap}.table th{background:var(--soft);color:var(--muted);font-size:.7rem;letter-spacing:.07em;text-transform:uppercase}.table tr:last-child td{border-bottom:0}.table tr:hover td{background:#fafcff}.rank{color:var(--muted);font-variant-numeric:tabular-nums}.player{font-weight:750}.fed{font-size:.72rem;font-weight:800;color:var(--muted);background:var(--soft);border-radius:4px;padding:.18rem .35rem}.num{text-align:right!important;font-variant-numeric:tabular-nums}.peak{font-weight:750}.sources details{border-top:1px solid var(--line);padding-top:.8rem}.sources summary{cursor:pointer;font-weight:750}.sources ul{padding-left:1.2rem;margin-bottom:0}.sources li{margin:.45rem 0;color:var(--muted);font-size:.84rem}.sources a{color:var(--blue)}@media(max-width:760px){.kpis{grid-template-columns:repeat(2,1fr)}.method-grid{grid-template-columns:1fr}.panel{padding:1rem}.panel-head{display:block}.chart{height:330px}.hero{padding-top:1.5rem}}@media(max-width:480px){.controls input{min-width:0;width:100%}.table-toolbar{display:block}.table-toolbar input{width:100%;margin-top:.5rem}}
</style>
<header class="hero"><p class="eyebrow">A data project · FIDE standard lists</p><h1>Chess FIDE Elo Explorer</h1><p class="sub">How has elite chess changed over time? Trace the players who shaped the top 100, then switch between published ratings and a peer-calibrated view.</p></header>
<div class="warning"><span aria-hidden="true">◆</span><div><strong>Coverage now reaches the first official FIDE list.</strong> This verified snapshot set covers <span id="coverage"></span>. The historical source includes the official lists from July 1971, while the modern archive continues through the latest available month. This page is a study of the observed archive, not an all-time leaderboard.</div></div>
<div class="kpis" id="kpis"></div>
<section class="panel"><div class="panel-head"><div><h2>Player trajectories</h2><p>Compare up to ten players across the available lists. Select a line below to hide it temporarily.</p></div></div><div class="controls"><label for="search">Add a player</label><input id="search" type="search" placeholder="Search by player name…" autocomplete="off"><select id="matches" aria-label="Player search results" hidden></select><button id="add-player" type="button">Add selected player</button><button class="mode active" data-mode="raw">Published rating</button><button class="mode" data-mode="cal">Peer-calibrated</button></div><div class="chart"><svg id="chart" viewBox="0 0 900 420" role="img" aria-label="Chess rating trajectories"></svg></div><div class="legend" id="legend"></div><p class="note" id="chart-note"></p></section>
<section class="method-grid"><article class="method-card"><span class="method-number">1</span><h3>Collect the lists</h3><p>Each snapshot contributes the players and ratings in that month's observed top 100.</p></article><article class="method-card"><span class="method-number">2</span><h3>Keep two lenses</h3><p>Published rating shows the number FIDE lists. Peer-calibrated rating adjusts for the strength of that month's elite field.</p></article><article class="method-card"><span class="method-number">3</span><h3>Read with restraint</h3><p>A peak is a peak within this archive. Gaps, name changes and source methodology limit what can be inferred.</p></article></section>
<section class="panel"><div class="panel-head"><div><h2>Observed peaks</h2><p>Sorted by peer-calibrated peak by default, because the calibrated series is the main comparison. Click any column heading to sort.</p></div></div><div class="table-toolbar"><span class="muted" id="table-count"></span><input id="table-search" type="search" placeholder="Filter this table…" aria-label="Filter observed peaks"></div><div class="table-wrap"><table class="table"><thead><tr><th><button class="sort" data-sort="rank" type="button">#</button></th><th><button class="sort" data-sort="name" type="button">Player</button></th><th><button class="sort" data-sort="fed" type="button">Fed.</button></th><th><button class="sort" data-sort="date" type="button">Peak month</button></th><th class="num"><button class="sort" data-sort="cal" type="button">Peer-calibrated</button></th><th class="num"><button class="sort" data-sort="raw" type="button">Raw peak</button></th></tr></thead><tbody id="top"></tbody></table></div></section>
<section class="panel sources"><details><summary>Sources, method and limitations</summary><ul><li><strong>Input.</strong> The July 1971–October 2000 lists were converted from the <a href="https://www.olimpbase.org/Elo/summary.html">OlimpBase historical archive</a>, which preserves the available historical lists but warns that they were manually assembled and contain errors. January 2001–September 2019 comes from the community-maintained <a href="https://github.com/anujdahiya24/FIDE">Anuj Dahiya FIDE mirror</a>. January 2020–September 2026 comes from monthly top-100 snapshots at <a href="https://2700chess.com/fide-top100-history">2700chess</a>, a secondary mirror of FIDE lists. They are labelled as mirrors, not direct official-FIDE downloads.</li><li><strong>Calibration.</strong> For each list, the page calculates the mean rating of the listed elite field. A player's calibrated value is raw rating − that list's mean + the latest list's mean. It compares position within the observed elite pool, not strength against an external era model.</li><li><strong>Limitations.</strong> Only players appearing in a supplied top-100 list are represented. The archive has uneven historical intervals before 2013, list methodology changes, federation/name changes, and the imperfect historical archive before 2001.</li></ul></details></section>
<script src="/assets/js/chess-elo-data.js"></script><script>(function(){const D=window.CHESS_ELO_DATA,players=D.players,dates=D.dates,means=D.means,colors=['#2457d6','#e05252','#159570','#8b5cf6','#c27a16','#087f9b','#d9467a','#6675d9','#4b8b3b','#a855f7'];let mode='raw',selected=players.slice(0,3).map(p=>p.name),off=new Set(),sortKey='cal',sortDir=-1;const $=id=>document.getElementById(id),esc=s=>s.replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));const player=n=>players.find(p=>p.name===n),value=(p,i)=>{const j=dates.indexOf(p.series[i][0]);return mode==='raw'?p.series[i][1]:p.series[i][1]-means[j]+D.referenceMean};$('coverage').textContent=D.coverage.start+' through '+D.coverage.end;[['Lists',D.coverage.lists],['Players',D.coverage.players],['Latest field mean',D.referenceMean],['Months',dates.length]].forEach(x=>{$('kpis').innerHTML+=`<div class="kpi"><div class="k-label">${x[0]}</div><div class="k-value">${x[1]}</div></div>`});function addSelected(){const n=$('matches').value;if(!n)return;if(!selected.includes(n)){if(selected.length>=10)selected.shift();selected.push(n)}$('search').value='';$('matches').value='';$('matches').hidden=true;render()}function renderLegend(){const c=$('legend');c.innerHTML='';selected.forEach((n,k)=>{const chip=document.createElement('span');chip.className='chip'+(off.has(n)?' off':'');const toggle=document.createElement('button');toggle.type='button';toggle.className='chip-toggle';toggle.setAttribute('aria-pressed',String(!off.has(n)));toggle.title=off.has(n)?'Show on chart':'Hide from chart';toggle.innerHTML=`<span style="color:${colors[k%colors.length]}">●</span> ${esc(n)}`;toggle.onclick=()=>{off.has(n)?off.delete(n):off.add(n);render()};const remove=document.createElement('button');remove.type='button';remove.className='chip-remove';remove.setAttribute('aria-label','Remove '+n);remove.title='Remove player';remove.textContent='×';remove.onclick=()=>{selected=selected.filter(x=>x!==n);off.delete(n);render()};chip.append(toggle,remove);c.append(chip)})}function render(){const svg=$('chart'),W=900,H=420,L=62,R=18,T=18,B=44,all=selected.flatMap(n=>{const p=player(n);return p?p.series.map((_,i)=>value(p,i)):[]});if(!all.length)return;let lo=Math.floor(Math.min(...all)/50)*50,hi=Math.ceil(Math.max(...all)/50)*50;if(hi===lo)hi+=100;const X=i=>L+i*(W-L-R)/(dates.length-1),Y=v=>T+(hi-v)*(H-T-B)/(hi-lo);let out='';for(let v=lo;v<=hi;v+=50)out+=`<line x1="${L}" x2="${W-R}" y1="${Y(v)}" y2="${Y(v)}" stroke="#e4e9f0"/><text x="${L-9}" y="${Y(v)+4}" text-anchor="end" font-size="11" fill="#718096">${v}</text>`;dates.forEach((d,i)=>{if(i%Math.ceil(dates.length/8)===0||i===dates.length-1)out+=`<text x="${X(i)}" y="${H-13}" text-anchor="middle" font-size="11" fill="#718096">${d}</text>`});selected.forEach((n,k)=>{const p=player(n);if(!p||off.has(n))return;const pts=p.series.map(q=>`${X(dates.indexOf(q[0]))},${Y(value(p,p.series.indexOf(q)))}`).join(' ');out+=`<polyline points="${pts}" fill="none" stroke="${colors[k%colors.length]}" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/>`});svg.innerHTML=out;$('chart-note').textContent=(mode==='raw'?'Published FIDE rating':'Peer-calibrated rating')+' · The lines connect each player’s available observations; missing months are left as gaps in the source archive.';renderLegend()}function drawTable(){const q=$('table-search').value.toLowerCase().trim();let rows=players.filter(p=>p.name.toLowerCase().includes(q));const get=p=>sortKey==='name'?p.name.toLowerCase():sortKey==='fed'?p.fed.toLowerCase():sortKey==='date'?p.peak.date:sortKey==='raw'?p.peak.rating:p.peak.calibrated;rows.sort((a,b)=>{const av=get(a),bv=get(b);return (av<bv?-1:av>bv?1:0)*sortDir||a.name.localeCompare(b.name)});const shown=rows.slice(0,20);$('table-count').textContent=`Showing ${shown.length} of ${rows.length} matching peaks`;$('top').innerHTML=shown.map((p,i)=>`<tr><td class="rank">${i+1}</td><td class="player">${esc(p.name)}</td><td><span class="fed">${esc(p.fed)}</span></td><td>${p.peak.date}</td><td class="num peak">${p.peak.calibrated.toFixed(2)}</td><td class="num">${p.peak.rating}</td></tr>`).join('');document.querySelectorAll('.sort').forEach(b=>{b.setAttribute('aria-sort',b.dataset.sort===sortKey?(sortDir===-1?'descending':'ascending'):'none');b.onclick=()=>{if(sortKey===b.dataset.sort)sortDir*=-1;else{sortKey=b.dataset.sort;sortDir=b.dataset.sort==='name'||b.dataset.sort==='fed'?1:-1}drawTable()}})}$('table-search').oninput=drawTable;$('search').oninput=function(){const q=this.value.toLowerCase().trim(),matches=q?players.filter(p=>p.name.toLowerCase().includes(q)).slice(0,20):[];$('matches').hidden=!matches.length;$('matches').innerHTML=matches.map(p=>`<option value="${esc(p.name)}">${esc(p.name)} (${esc(p.fed)})</option>`).join('')};$('add-player').onclick=addSelected;$('search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();addSelected()}};document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x===b));render()});drawTable();render()})()</script></div></body></html>'''
PAGE.write_text(front + "\n\n" + template, encoding="utf-8")
print(f"wrote {ASSET} ({ASSET.stat().st_size} bytes), {PAGE} ({PAGE.stat().st_size} bytes), {len(files)} lists, {len(players)} players")
